def sha_bytes(b): return hashlib.sha256(b).hexdigest()
def sha_json(x): return sha_bytes(json.dumps(x,sort_keys=True,default=str,separators=(',',':')).encode())
def source_sha(): return sha_bytes(SOURCE.read_bytes())
def seed_for(seed,name): return int.from_bytes(hashlib.sha256(f'{seed}:{name}'.encode()).digest()[:8],'little') & ((1<<63)-1)
def rng_for(seed,name): return np.random.default_rng(seed_for(seed,name))
def _load_graph():
    raw=zlib.decompress(base64.b85decode(_GRAPH_PAYLOAD.encode()))
    if sha_bytes(raw)!=GRAPH_PAYLOAD_SHA256: raise RuntimeError('embedded graph payload hash mismatch')
    return pickle.loads(raw)
GRAPH=_load_graph()
PN_IDS=np.asarray(GRAPH['pn_ids'],dtype=np.uint64);KC_IDS=np.asarray(GRAPH['kc_ids'],dtype=np.uint64);MBON_IDS=np.asarray(GRAPH['mbon_ids'],dtype=np.uint64)
PK_PRE=np.asarray(GRAPH['pk_pre'],dtype=np.int32);PK_POST=np.asarray(GRAPH['pk_post'],dtype=np.int32);PK_COUNT=np.asarray(GRAPH['pk_count'],dtype=np.float64)
KM_PRE=np.asarray(GRAPH['km_pre'],dtype=np.int32);KM_POST=np.asarray(GRAPH['km_post'],dtype=np.int16);KM_COUNT=np.asarray(GRAPH['km_count'],dtype=np.float64)
assert len(PN_IDS)==PN_N and len(KC_IDS)==KC_N and len(MBON_IDS)==MBON_N
assert len(PK_PRE)==22417 and int(round(PK_COUNT.sum()))==168315
assert len(KM_PRE)==15523 and int(round(KM_COUNT.sum()))==28415
KM_EDGES_BY_KC=[np.flatnonzero(KM_PRE==k).astype(np.int32) for k in range(KC_N)]
def active_km_edges(z):
    act=np.flatnonzero(z)
    if len(act)==0:return np.empty(0,dtype=np.int32)
    parts=[KM_EDGES_BY_KC[int(k)] for k in act if len(KM_EDGES_BY_KC[int(k)])]
    return np.concatenate(parts) if parts else np.empty(0,dtype=np.int32)
PK_DEN=np.bincount(PK_POST,weights=PK_COUNT,minlength=KC_N)
PK_SCALE=np.sqrt(PK_COUNT)/np.sqrt(np.maximum(PK_DEN[PK_POST],1e-12))

T95={1:12.706,2:4.303,3:3.182,4:2.776,5:2.571,6:2.447,7:2.365,8:2.306,9:2.262,10:2.228,11:2.201,12:2.179,13:2.160,14:2.145,15:2.131}
def interval(vals):
    vals=[float(v) for v in vals if v is not None and math.isfinite(float(v))];n=len(vals)
    if not vals:return {'n':0,'mean':None,'low':None,'high':None}
    m=float(np.mean(vals))
    if n<2:return {'n':n,'mean':m,'low':None,'high':None}
    sd=float(np.std(vals,ddof=1));t=T95.get(n-1,1.96);h=t*sd/math.sqrt(n)
    return {'n':n,'mean':m,'sd':sd,'low':m-h,'high':m+h}
def paired(seed_results,left,right,key):
    vals=[]
    for r in seed_results:
        a=r['terminal'][left].get(key);b=r['terminal'][right].get(key)
        if a is not None and b is not None:vals.append(float(a)-float(b))
    return interval(vals)
def softmax(x):
    x=np.asarray(x,dtype=np.float64);x=x-np.max(x);p=np.exp(x);return p/max(float(p.sum()),1e-300)
def bpb(p,y):return -math.log2(max(float(p[int(y)]),1e-300))
def atomic_json(path,obj):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True);tmp=path.with_suffix(path.suffix+'.tmp');tmp.write_text(json.dumps(obj,indent=1,default=str));os.replace(tmp,path)
def atomic_gzip_json(path,obj):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True);tmp=path.with_suffix(path.suffix+'.tmp')
    with gzip.open(tmp,'wt') as f:json.dump(obj,f,default=str,separators=(',',':'))
    os.replace(tmp,path)
def load_gzip_json(path):
    with gzip.open(path,'rt') as f:return json.load(f)
def write_csv(path,rows):
    path=Path(path);path.parent.mkdir(parents=True,exist_ok=True);rows=list(rows)
    if not rows:path.write_text('');return
    fields=[]
    for r in rows:
        for k in r:
            if k not in fields:fields.append(k)
    with path.open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows(rows)
def rss_bytes():
    r=int(resource.getrusage(resource.RUSAGE_SELF).ru_maxrss);return r if sys.platform.startswith('darwin') else r*1024

class RawSensory:
    def pn_to_drive(self,pn):
        vals=PK_SCALE*pn[PK_PRE]
        return np.bincount(PK_POST,weights=vals,minlength=KC_N)
    def cue_codes(self,frames):
        state=np.zeros(KC_N,dtype=np.float64);static=None
        for pn in frames:
            a=np.tanh(self.pn_to_drive(pn))
            state=RHO*state+(1.-RHO)*a
            static=a
        return self._sparse(state),self._sparse(static)
    @staticmethod
    def _sparse(a):
        ix=np.argpartition(-np.abs(a),KC_ACTIVE-1)[:KC_ACTIVE];v=a[ix];n=float(np.linalg.norm(v));z=np.zeros(KC_N,dtype=np.float64);z[ix]=v/max(n,1e-12);return z


