# ------------------------------ core feature rule -----------------------------
class EligibilitySensory(RawSensory):
    def cue_features(self,frames):
        state=np.zeros(KC_N,dtype=np.float64)
        elig=np.zeros(KC_N,dtype=np.float64)
        for pn in frames:
            a=np.tanh(self.pn_to_drive(pn))
            state=RHO*state+(1.-RHO)*a
            elig=ELIG_DECAY*elig+self._sparse(state)
        z=self._sparse(state)
        # Exact omnibus operation: positive scalar blank-step then sparse normalize.
        zelig=self._sparse(ELIG_DECAY*elig)
        return z,zelig

class Memory:
    def __init__(self):
        self.theta=np.zeros(len(KM_PRE),dtype=np.float64)
        self.update_events=0; self.nonzero_update_events=0; self.touched_synapses=0
        self.update_l1=0.; self.update_l2=0.; self.update_l2_sq=0.
    def predict(self,z,C,tau=TAU):
        ed=active_km_edges(z)
        if len(ed):
            h=np.bincount(KM_POST[ed],weights=self.theta[ed]*z[KM_PRE[ed]],minlength=MBON_N)
        else: h=np.zeros(MBON_N,dtype=np.float64)
        return softmax((C@h)/tau)
    def update(self,zwrite,teacher,C,p,eta=ETA):
        self.update_events+=1
        ed=active_km_edges(zwrite)
        if not len(ed): return
        e=RESIDUAL_SCALE*(C[int(teacher)]-(p@C))
        delta=eta*zwrite[KM_PRE[ed]]*e[KM_POST[ed]]
        self.theta[ed]+=delta
        self.nonzero_update_events+=1; self.touched_synapses+=int(len(ed))
        l2=float(np.linalg.norm(delta)); self.update_l1+=float(np.abs(delta).sum()); self.update_l2+=l2; self.update_l2_sq+=l2*l2
    def update_edges(self,ed,preval,post,teacher,C,p,eta=ETA):
        self.update_events+=1
        if not len(ed): return
        e=RESIDUAL_SCALE*(C[int(teacher)]-(p@C))
        delta=eta*preval*e[post]
        self.theta[ed]+=delta
        self.nonzero_update_events+=1; self.touched_synapses+=int(len(ed))
        l2=float(np.linalg.norm(delta)); self.update_l1+=float(np.abs(delta).sum()); self.update_l2+=l2; self.update_l2_sq+=l2*l2
    def clone(self):
        q=Memory(); q.theta=self.theta.copy(); q.update_events=self.update_events; q.nonzero_update_events=self.nonzero_update_events
        q.touched_synapses=self.touched_synapses; q.update_l1=self.update_l1; q.update_l2=self.update_l2; q.update_l2_sq=self.update_l2_sq
        return q
    def stats(self):
        return {'update_events':self.update_events,'nonzero_update_events':self.nonzero_update_events,'touched_synapses':self.touched_synapses,
                'sum_update_l1':self.update_l1,'sum_update_l2':self.update_l2,'sum_squared_update_l2':self.update_l2_sq,
                'final_weight_l1':float(np.abs(self.theta).sum()),'final_weight_l2':float(np.linalg.norm(self.theta)),'final_weight_nnz':int(np.count_nonzero(self.theta))}

class Panel:
    def __init__(self,C):
        self.C=np.asarray(C,dtype=np.float64)
        self.mem={a:Memory() for a in ARMS if a!='NOLEARN'}
        self.zero=Memory()
    def predict(self,arm,zread):
        return (self.zero if arm=='NOLEARN' else self.mem[arm]).predict(zread,self.C)
    def update(self,arm,zread,zelig,teacher,p=None):
        if arm=='NOLEARN': return
        if p is None: p=self.predict(arm,zread)
        zw=zelig if arm in ('ELIG-WRITE','UNPAIRED-ELIG') else zread
        self.mem[arm].update(zw,teacher,self.C,p)
    def predict_all(self,zread):
        ed=active_km_edges(zread); post=KM_POST[ed]; preval=zread[KM_PRE[ed]] if len(ed) else np.empty(0,dtype=np.float64)
        H=np.zeros((len(ARMS),MBON_N),dtype=np.float64)
        for ai,arm in enumerate(ARMS):
            if arm=='NOLEARN' or not len(ed): continue
            H[ai]=np.bincount(post,weights=self.mem[arm].theta[ed]*preval,minlength=MBON_N)
        logits=(H@self.C.T)/TAU; logits-=logits.max(axis=1,keepdims=True); P=np.exp(logits); P/=P.sum(axis=1,keepdims=True)
        return {arm:P[ai] for ai,arm in enumerate(ARMS)}
    def update_all(self,zread,zelig,teachers,ps):
        er=active_km_edges(zread); pr=zread[KM_PRE[er]] if len(er) else np.empty(0,dtype=np.float64); por=KM_POST[er]
        ee=active_km_edges(zelig); pe=zelig[KM_PRE[ee]] if len(ee) else np.empty(0,dtype=np.float64); poe=KM_POST[ee]
        for arm in ARMS:
            if arm=='NOLEARN': continue
            if arm in ('ELIG-WRITE','UNPAIRED-ELIG'): self.mem[arm].update_edges(ee,pe,poe,teachers[arm],self.C,ps[arm])
            else: self.mem[arm].update_edges(er,pr,por,teachers[arm],self.C,ps[arm])
    def state_hash(self):
        h=hashlib.sha256()
        for a in sorted(self.mem): h.update(a.encode()); h.update(self.mem[a].theta.tobytes()); h.update(str(self.mem[a].update_events).encode())
        return h.hexdigest()

@dataclass
class SumMetric:
    n:int=0; loss_sum:float=0.; correct:int=0; probability_sum:float=0.
    def add(self,p,y):
        self.n+=1; self.loss_sum+=bpb(p,y); self.correct+=int(int(np.argmax(p))==int(y)); self.probability_sum+=float(p[int(y)])
    def row(self):
        n=self.n
        return {'n':n,'loss_sum':self.loss_sum,'correct_count':self.correct,'probability_sum':self.probability_sum,
                'bpb':self.loss_sum/n if n else None,'accuracy':self.correct/n if n else None,'mean_true_probability':self.probability_sum/n if n else None}

# ------------------------------- cue task -------------------------------------
class CueWorldV51:
    def __init__(self,seed,load,smoke=False):
        self.seed=int(seed); self.requested_load=int(load); self.n_per=8 if smoke else int(load)//4; self.n=4*self.n_per
        self.active=np.zeros((self.n,CUE_ACTIVE_PN),dtype=np.int16); self.amp=np.zeros((self.n,CUE_ACTIVE_PN),dtype=np.float64)
        for i in range(self.n):
            rg=rng_for(seed,f'proto:{i}'); self.active[i]=np.sort(rg.choice(PN_N,CUE_ACTIVE_PN,replace=False)); self.amp[i]=rg.uniform(.7,1.,CUE_ACTIVE_PN)
        self.labels=np.zeros(self.n,dtype=np.int16)
        for c in range(4):
            ids=np.arange(c*self.n_per,(c+1)*self.n_per); lab=np.resize(np.arange(OUTCOMES,dtype=np.int16),len(ids)); rng_for(seed,f'label:{c}').shuffle(lab); self.labels[ids]=lab
        a=np.arange(self.n_per); self.untouched=a[:self.n_per//2].tolist(); self.noisy=a[self.n_per//2:3*self.n_per//4].tolist(); self.revised=a[3*self.n_per//4:].tolist()
        self.changed={int(i):int((int(self.labels[i])+1+int(rng_for(seed,f'rev:{i}').integers(OUTCOMES-1)))%OUTCOMES) for i in self.revised}
    def cohort_ids(self,c): return list(range(c*self.n_per,(c+1)*self.n_per))
    def frames(self,i,family,variant=0):
        i=int(i); rg=rng_for(self.seed,f'render:{i}:{int(family)}:{int(variant)}'); base=self.active[i]; amp=self.amp[i]; frames=[]
        keep_n=int(round(RETAIN*CUE_ACTIVE_PN)); inactive=np.setdiff1d(np.arange(PN_N),base,assume_unique=False)
        for _ in range(CUE_FRAMES):
            keep=np.sort(rg.choice(CUE_ACTIVE_PN,keep_n,replace=False)); drop_n=CUE_ACTIVE_PN-keep_n; rep=np.sort(rg.choice(inactive,drop_n,replace=False)) if drop_n else np.array([],dtype=int)
            x=np.zeros(PN_N,dtype=np.float64); jitter=np.clip(1.+rg.normal(0,AMP_SD,keep_n),.5,1.5); x[base[keep]]=np.clip(amp[keep]*jitter,0,1)
            if drop_n: x[rep]=rg.uniform(.7,1.,drop_n)
            frames.append(x)
        return np.stack(frames)

def outcome_codebook(seed,nout,name):
    rg=rng_for(seed,name); C=(2*rg.integers(0,2,size=(nout,MBON_N))-1).astype(np.float64); C/=np.linalg.norm(C,axis=1,keepdims=True); return C

def make_unpaired_targets(seed,cohort,exposure,ids,labels):
    y=np.array([int(labels[i]) for i in ids],dtype=int); rg=rng_for(seed,f'unpaired:{cohort}:{exposure}')
    for _ in range(20):
        q=y[rg.permutation(len(y))]
        if np.mean(q==y)<=.35: return q
    return np.roll(y,1)

def cue_codes_for(world,sens,ids,family,variant):
    return {int(i):sens.cue_features(world.frames(int(i),family,variant+int(i))) for i in ids}

def probe_codes(panel,codes,labels,task,load,seed,checkpoint,rows,mark='association'):
    before=panel.state_hash()
    for arm in ARMS:
        m=SumMetric()
        for i,(zr,ze) in codes.items(): m.add(panel.predict(arm,zr),int(labels[int(i)]))
        rows.append({'seed':seed,'task':task,'load':load,'arm':arm,'checkpoint':checkpoint,'probe_kind':mark,**m.row()})
    assert before==panel.state_hash(),'probe mutated learner state'

def cue_train_wave(world,sens,panel,cohort,preq,obs_counter,smoke=False):
    ids=world.cohort_ids(cohort); cname='ABCD'[cohort]; reps=3 if smoke else REPEATS
    for ex in range(reps):
        order=np.array(ids); rng_for(world.seed,f'order:{cname}:{ex}').shuffle(order); unp=make_unpaired_targets(world.seed,cname,ex,order,world.labels)
        for j,i0 in enumerate(order):
            i=int(i0); zr,ze=sens.cue_features(world.frames(i,ex%2,ex)); true=int(world.labels[i])
            for arm in ARMS:
                p=panel.predict(arm,zr); mem=panel.mem.get(arm)
                preq.append({'seed':world.seed,'task':'CUE8','load':world.requested_load,'arm':arm,'cohort':cname,'identity_eval_only':i,'exposure_index':ex+1,'prior_exposures':ex,
                             'correct':int(np.argmax(p)==true),'true_probability':float(p[true]),'loss_bits':bpb(p,true),'observations_so_far':obs_counter[0],'updates_so_far':mem.update_events if mem else 0})
                teacher=int(unp[j]) if arm.startswith('UNPAIRED') else true
                panel.update(arm,zr,ze,teacher,p)
            obs_counter[0]+=1

def cue_trial(seed,load,smoke=False):
    t0=time.perf_counter(); world=CueWorldV51(seed,load,smoke); sens=EligibilitySensory(); C=outcome_codebook(seed,OUTCOMES,'outcome-code'); panel=Panel(C)
    probes=[]; preq=[]; noise=[]; rev=[]; obs_counter=[0]
    # A
    cue_train_wave(world,sens,panel,0,preq,obs_counter,smoke)
    probe_codes(panel,cue_codes_for(world,sens,world.cohort_ids(0),0,9000),world.labels,'CUE8',load,seed,'after_A_trained',probes)
    probe_codes(panel,cue_codes_for(world,sens,world.cohort_ids(0),2,9100),world.labels,'CUE8',load,seed,'after_A_heldout',probes)
    # B and first return
    cue_train_wave(world,sens,panel,1,preq,obs_counter,smoke)
    probe_codes(panel,cue_codes_for(world,sens,world.cohort_ids(0),2,9200),world.labels,'CUE8',load,seed,'A_first_return_after_B',probes)
    probe_codes(panel,cue_codes_for(world,sens,world.cohort_ids(1),2,9300),world.labels,'CUE8',load,seed,'B_after_B_heldout',probes)
    # paired before/after one-off corruption
    ncode=cue_codes_for(world,sens,world.noisy,2,9400)
    before={}
    for arm in ARMS:
        m=SumMetric()
        for i,(zr,ze) in ncode.items(): m.add(panel.predict(arm,zr),int(world.labels[i]))
        before[arm]=m.row()
    for i in world.noisy:
        wrong=(int(world.labels[i])+1+int(rng_for(seed,f'noise:{i}').integers(OUTCOMES-1)))%OUTCOMES; zr,ze=sens.cue_features(world.frames(i,0,9450+i))
        for arm in ARMS:
            p=panel.predict(arm,zr); panel.update(arm,zr,ze,wrong,p)
        obs_counter[0]+=1
    for arm in ARMS:
        m=SumMetric()
        for i,(zr,ze) in ncode.items(): m.add(panel.predict(arm,zr),int(world.labels[i]))
        a=m.row(); noise.append({'seed':seed,'task':'CUE8','load':load,'arm':arm,'before_accuracy':before[arm]['accuracy'],'after_accuracy':a['accuracy'],'accuracy_change':a['accuracy']-before[arm]['accuracy'],
                      'before_bpb':before[arm]['bpb'],'after_bpb':a['bpb'],'bpb_change':a['bpb']-before[arm]['bpb']})
    # C
    cue_train_wave(world,sens,panel,2,preq,obs_counter,smoke)
    for c,name in ((0,'A_untouched_after_C_heldout'),(1,'B_after_C_heldout'),(2,'C_after_C_heldout')):
        ids=world.untouched if c==0 else world.cohort_ids(c); probe_codes(panel,cue_codes_for(world,sens,ids,2,9500+100*c),world.labels,'CUE8',load,seed,name,probes)
    # revision; shared unpaired permutation within each exposure
    rev_reps=2 if smoke else 8; rev_probe=cue_codes_for(world,sens,world.revised,2,9700)
    for ex in range(1,rev_reps+1):
        ids=np.array(world.revised); rng_for(seed,f'revorder:{ex}').shuffle(ids); true_new=np.array([world.changed[int(i)] for i in ids],dtype=int); rg=rng_for(seed,f'unpaired-rev:{ex}'); unp=true_new[rg.permutation(len(true_new))] if len(true_new)>1 else true_new.copy()
        assert sorted(map(int,unp))==sorted(map(int,true_new))
        for j,i0 in enumerate(ids):
            i=int(i0); zr,ze=sens.cue_features(world.frames(i,0,9600+ex*100+i)); new=int(world.changed[i]); old=int(world.labels[i])
            for arm in ARMS:
                p=panel.predict(arm,zr)
                rev.append({'seed':seed,'task':'CUE8','load':load,'arm':arm,'row_type':'preupdate','exposure':ex,'identity_eval_only':i,'new_correct':int(np.argmax(p)==new),'new_probability':float(p[new]),'new_bpb':bpb(p,new),'old_probability':float(p[old]),'old_bpb':bpb(p,old)})
                teacher=int(unp[j]) if arm.startswith('UNPAIRED') else new; panel.update(arm,zr,ze,teacher,p)
            obs_counter[0]+=1
        if ex in (1,2,4,8):
            for arm in ARMS:
                mn=SumMetric(); oldprob=[]
                for i,(zr,ze) in rev_probe.items():
                    p=panel.predict(arm,zr); new=int(world.changed[i]); old=int(world.labels[i]); mn.add(p,new); oldprob.append(float(p[old]))
                rr=mn.row(); rev.append({'seed':seed,'task':'CUE8','load':load,'arm':arm,'row_type':'probe','exposure':ex,'new_accuracy':rr['accuracy'],'new_probability':rr['mean_true_probability'],'new_bpb':rr['bpb'],'old_probability':float(np.mean(oldprob))})
    # D
    cue_train_wave(world,sens,panel,3,preq,obs_counter,smoke)
    finals=[('A_untouched_after_D_trained',world.untouched,0,world.labels),('A_untouched_after_D_heldout',world.untouched,2,world.labels),('A_noise_after_D_heldout',world.noisy,2,world.labels),
            ('A_revision_after_D_heldout',world.revised,2,world.changed),('B_after_D_heldout',world.cohort_ids(1),2,world.labels),('C_after_D_heldout',world.cohort_ids(2),2,world.labels),
            ('D_after_D_trained',world.cohort_ids(3),0,world.labels),('D_after_D_heldout',world.cohort_ids(3),2,world.labels)]
    for k,(name,ids,fam,labs) in enumerate(finals): probe_codes(panel,cue_codes_for(world,sens,ids,fam,10000+100*k),labs,'CUE8',load,seed,name,probes)
    # localization: identical A untouched held-out panel for intact/reset/shuffle
    loc_codes=cue_codes_for(world,sens,world.untouched,2,12000); loc=[]
    for arm in REAL_ARMS:
        base=panel.mem[arm]
        variants={'intact':base,'reset':Memory()}
        sh=base.clone(); rg=rng_for(seed,f'synapse-shuffle:{arm}')
        for j in range(MBON_N):
            ix=np.flatnonzero(KM_POST==j); v=sh.theta[ix].copy(); rg.shuffle(v); sh.theta[ix]=v
        variants['shuffle']=sh
        for lesion,mem in variants.items():
            m=SumMetric()
            for i,(zr,ze) in loc_codes.items(): m.add(mem.predict(zr,C),int(world.labels[i]))
            loc.append({'seed':seed,'task':'CUE8','load':load,'arm':arm,'lesion':lesion,**m.row()})
    # audits/costs
    state=[]; updates=[]
    graph_bytes=sum(x.nbytes for x in (PN_IDS,KC_IDS,MBON_IDS,PK_PRE,PK_POST,PK_COUNT,KM_PRE,KM_POST,KM_COUNT,PK_SCALE))
    for arm in ARMS:
        mem=panel.mem.get(arm)
        updates.append({'seed':seed,'task':'CUE8','load':load,'arm':arm,**(mem.stats() if mem else Memory().stats())})
        state.append({'seed':seed,'task':'CUE8','load':load,'arm':arm,'learned_bytes':0 if arm=='NOLEARN' else len(KM_PRE)*8,'kc_transient_bytes':KC_N*8,'eligibility_transient_bytes':KC_N*8 if 'ELIG' in arm else 0,
                      'codebook_bytes':C.nbytes,'graph_fixed_bytes':graph_bytes,'adaptor_fixed_bytes':0,'feature_cache_cap_bytes':0})
    return {'identity':EXPERIMENT_NAMESPACE,'seed':seed,'task':'CUE8','load':load,'effective_load':world.n,'smoke':bool(smoke),'prequential':preq,'probes':probes,'noise':noise,'revision':rev,'localization':loc,'updates':updates,'state_costs':state,
            'sample_budget':{'seed':seed,'task':'CUE8','load':load,'identities':world.n,'teacher_events':int((8*world.n)+(len(world.noisy))+(rev_reps*len(world.revised))),'cue_frames_per_teacher':4,'raw_input_frames':int(4*((8*world.n)+len(world.noisy)+rev_reps*len(world.revised)))},
            'elapsed_seconds':time.perf_counter()-t0,'peak_rss':rss_bytes(),'codebook_rank':int(np.linalg.matrix_rank(C))}

# ------------------------------- byte task ------------------------------------
def surface_context(key,wrapper):
    k=bytearray(key); m=KEY_XOR_MASKS[int(wrapper)]; k[0]^=m[0]; k[1]^=m[1]; return PREFIX+HEADERS[int(wrapper)]+bytes(k)+SEPARATORS[int(wrapper)]
def context_bits(history):
    b=bytes(history)[-12:]; out=np.zeros(CONTEXT_D)
    if b:
        a=BYTE_PERM[np.frombuffer(b,dtype=np.uint8)]; bits=BIT_CODE[a].ravel(); out[-len(bits):]=bits
    return out

def _compress(z):
    ix=np.flatnonzero(z).astype(np.int32); return (ix,z[ix].astype(np.float64))
def _expand(c):
    z=np.zeros(KC_N,dtype=np.float64); z[c[0]]=c[1]; return z

class ByteFeatureCore:
    def __init__(self,seed):
        self.seed=int(seed); self.sens=EligibilitySensory(); rg=rng_for(seed,'byte-adaptor')
        self.idx=np.stack([rg.choice(CONTEXT_D,ADAPTOR_CONTACTS,replace=False) for _ in range(PN_N)]); self.sgn=(2*rg.integers(0,2,(PN_N,ADAPTOR_CONTACTS))-1)/math.sqrt(ADAPTOR_CONTACTS)
        self.cache=collections.OrderedDict(); self.cache_cap=BYTE_CACHE_CAP; self.hits=0; self.misses=0
    def features(self,history,use_cache=True):
        key=bytes(history)[-12:]
        if use_cache and key in self.cache:
            self.hits+=1; c=self.cache.pop(key); self.cache[key]=c; return _expand(c[0]),_expand(c[1])
        self.misses+=1; x=context_bits(history); frames=[]
        for f in range(4):
            xf=np.zeros(CONTEXT_D); xf[f*24:(f+1)*24]=x[f*24:(f+1)*24]; pn=np.tanh(np.einsum('pc,pc->p',xf[self.idx],self.sgn,optimize=True)); frames.append(pn)
        zr,ze=self.sens.cue_features(np.stack(frames)); c=(_compress(zr),_compress(ze))
        if use_cache:
            self.cache[key]=c
            if len(self.cache)>self.cache_cap:self.cache.popitem(last=False)
        return zr,ze
    def approx_cache_bytes(self):
        return int(sum(a[0].nbytes+a[1].nbytes+b[0].nbytes+b[1].nbytes for a,b in self.cache.values()))

class ByteWorldV51:
    def __init__(self,seed,load,smoke=False):
        self.seed=int(seed); self.requested_load=int(load); rr=np.random.default_rng(int(seed)+810007); self.count=4 if smoke else int(load)//4; self.reps=2 if smoke else 8
        self.keys=[]; alphabet=np.frombuffer(b'0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ',dtype=np.uint8)
        while len(self.keys)<self.count*4:
            k=bytes(rr.choice(alphabet,6))
            if k not in self.keys:self.keys.append(k)
        self.labels=rr.choice(np.frombuffer(b'abcdefghijklmnopqrstuvwx',dtype=np.uint8),size=len(self.keys)).astype(int)
        nrev=max(1,self.count//4); self.revised=list(range(nrev)); self.noisy=list(range(nrev,2*nrev)); self.changed={i:int(ord('a')+(int(self.labels[i])-ord('a')+1+int(rr.integers(23)))%24) for i in self.revised}
        self.acq={}; self.revb={}
        # Generate in exact V50 order, preserving the same rr evolution.
        for w in range(4):
            for ex in range(self.reps): self.acq[(w,ex+1)]=list(map(int,rr.permutation(np.arange(w*self.count,(w+1)*self.count))))
            if w==2:
                for ex in range(2 if smoke else 8): self.revb[ex+1]=list(map(int,rr.permutation(self.revised)))
    def cohort_ids(self,c): return list(range(c*self.count,(c+1)*self.count))
    def record(self,i,target,kind,exposure,wave,wrapper):
        return {'key_id':int(i),'target':int(target),'kind':kind,'exposure':int(exposure),'wave':'ABCD'[int(wave)],'wrapper':int(wrapper),'raw':surface_context(self.keys[int(i)],wrapper)+bytes([int(target)])+b'\n'}

class Markov2:
    def __init__(self):
        self.c2=np.zeros((65536,256),dtype=np.uint32); self.t2=np.zeros(65536,dtype=np.uint32); self.c1=np.zeros((256,256),dtype=np.uint32); self.t1=np.zeros(256,dtype=np.uint32); self.c0=np.zeros(256,dtype=np.uint32); self.t0=0
    def score(self,history,y):
        y=int(y)
        if len(history)>=2:
            k=(int(history[-2])<<8)|int(history[-1]); cy=int(self.c2[k,y]); total=int(self.t2[k]); pred=int(np.argmax(self.c2[k])) if total else 0
        elif len(history)==1:
            k=int(history[-1]); cy=int(self.c1[k,y]); total=int(self.t1[k]); pred=int(np.argmax(self.c1[k])) if total else 0
        else:
            cy=int(self.c0[y]); total=int(self.t0); pred=int(np.argmax(self.c0)) if total else 0
        prob=(cy+1.)/(total+256.); return {'prob':prob,'bpb':-math.log2(prob),'correct':int(pred==y)}
    def update(self,history,y):
        y=int(y); self.c0[y]+=1; self.t0+=1
        if len(history)>=1:
            k=int(history[-1]); self.c1[k,y]+=1; self.t1[k]+=1
        if len(history)>=2:
            k=(int(history[-2])<<8)|int(history[-1]); self.c2[k,y]+=1; self.t2[k]+=1
    def bytes(self): return int(self.c2.nbytes+self.t2.nbytes+self.c1.nbytes+self.t1.nbytes+self.c0.nbytes)

def class_of_pos(pos): return 'target' if pos==12 else ('key' if 5<=pos<=10 else 'framing')

def unpaired_map(seed,tag,ids,targets):
    ids=list(map(int,ids)); y=np.array(list(map(int,targets)),dtype=int); rg=rng_for(seed,'byte-unpaired:'+tag); q=y[rg.permutation(len(y))] if len(y)>1 else y.copy(); assert sorted(map(int,q))==sorted(map(int,y)); return {i:int(v) for i,v in zip(ids,q)}

def byte_probe_codes(core,world,ids,wrapper):
    return {int(i):core.features(surface_context(world.keys[int(i)],wrapper),use_cache=False) for i in ids}

def byte_probe(panel,core,world,ids,labels,wrapper,seed,load,checkpoint,rows,markov=None,markov_rows=None):
    codes=byte_probe_codes(core,world,ids,wrapper); before=panel.state_hash()
    for arm in ARMS:
        m=SumMetric()
        for i,(zr,ze) in codes.items():m.add(panel.predict(arm,zr),int(labels[int(i)]))
        rows.append({'seed':seed,'task':'BYTE256','load':load,'arm':arm,'checkpoint':checkpoint,'wrapper':wrapper,**m.row()})
    assert before==panel.state_hash()
    if markov is not None and markov_rows is not None:
        m=SumMetric()
        for i in ids:
            y=int(labels[int(i)]); sc=markov.score(surface_context(world.keys[int(i)],wrapper),y); m.n+=1;m.loss_sum+=sc['bpb'];m.correct+=sc['correct'];m.probability_sum+=sc['prob']
        markov_rows.append({'seed':seed,'task':'BYTE256','load':load,'kind':'probe','checkpoint':checkpoint,'wrapper':wrapper,**m.row()})
    return codes

def byte_trial(seed,load,smoke=False):
    t0=time.perf_counter(); world=ByteWorldV51(seed,load,smoke); core=ByteFeatureCore(seed); C=outcome_codebook(seed,BYTE_OUTPUTS,'byte-code'); panel=Panel(C); markov=Markov2(); hist=bytearray()
    preq=[]; probes=[]; noise=[]; rev=[]; markov_rows=[]; class_metrics=collections.defaultdict(SumMetric); global_obs=0
    def add_stream_metric(arm,p,y,cls,full):
        for sub in ('all',)+(('full_context',) if full else ()): 
            class_metrics[(arm,sub,'whole')].add(p,y); class_metrics[(arm,sub,cls)].add(p,y)
    def process_record(rec,unpaired=None,revision_log=False):
        nonlocal global_obs
        i=int(rec['key_id']); target=int(rec['target']); kind=rec['kind']; ex=int(rec['exposure']); cohort=rec['wave']; raw=rec['raw']
        for pos,y0 in enumerate(raw):
            y=int(y0); zr,ze=core.features(hist,True); cls=class_of_pos(pos); full=len(hist)>=12
            ps=panel.predict_all(zr)
            for arm,p in ps.items():
                add_stream_metric(arm,p,y,cls,full)
                if cls=='target' and kind=='acquisition':
                    mem=panel.mem.get(arm); preq.append({'seed':seed,'task':'BYTE256','load':load,'arm':arm,'cohort':cohort,'identity_eval_only':i,'exposure_index':ex,'prior_exposures':ex-1,'correct':int(np.argmax(p)==y),
                               'true_probability':float(p[y]),'loss_bits':bpb(p,y),'observations_so_far':global_obs,'updates_so_far':mem.update_events if mem else 0})
                if cls=='target' and kind=='revision' and revision_log:
                    old=int(world.labels[i]); rev.append({'seed':seed,'task':'BYTE256','load':load,'arm':arm,'row_type':'preupdate','exposure':ex,'identity_eval_only':i,'new_correct':int(np.argmax(p)==y),'new_probability':float(p[y]),'new_bpb':bpb(p,y),'old_probability':float(p[old]),'old_bpb':bpb(p,old)})
            msc=markov.score(hist,y)
            for sub in ('all',)+(('full_context',) if full else ()):
                key=('MARKOV2',sub,'whole'); class_metrics[key].n+=1;class_metrics[key].loss_sum+=msc['bpb'];class_metrics[key].correct+=msc['correct'];class_metrics[key].probability_sum+=msc['prob']
                key=('MARKOV2',sub,cls); class_metrics[key].n+=1;class_metrics[key].loss_sum+=msc['bpb'];class_metrics[key].correct+=msc['correct'];class_metrics[key].probability_sum+=msc['prob']
            teachers={}
            for arm in ARMS:
                teacher=y
                if cls=='target' and unpaired is not None and arm.startswith('UNPAIRED'): teacher=int(unpaired[i])
                teachers[arm]=teacher
            panel.update_all(zr,ze,teachers,ps)
            markov.update(hist,y); hist.append(y)
            if len(hist)>12:del hist[0]
            global_obs+=1
    # A
    for ex in range(1,world.reps+1):
        ids=world.acq[(0,ex)]; up=unpaired_map(seed,f'acq:0:{ex}',ids,[world.labels[i] for i in ids])
        for i in ids: process_record(world.record(i,world.labels[i],'acquisition',ex,0,(ex-1)%2),up)
    byte_probe(panel,core,world,world.cohort_ids(0),world.labels,0,seed,load,'after_A_trained',probes,markov,markov_rows); byte_probe(panel,core,world,world.cohort_ids(0),world.labels,2,seed,load,'after_A_heldout',probes,markov,markov_rows)
    # B
    for ex in range(1,world.reps+1):
        ids=world.acq[(1,ex)]; up=unpaired_map(seed,f'acq:1:{ex}',ids,[world.labels[i] for i in ids])
        for i in ids: process_record(world.record(i,world.labels[i],'acquisition',ex,1,(ex-1)%2),up)
    byte_probe(panel,core,world,world.cohort_ids(0),world.labels,2,seed,load,'A_first_return_after_B',probes,markov,markov_rows); byte_probe(panel,core,world,world.cohort_ids(1),world.labels,2,seed,load,'B_after_B_heldout',probes,markov,markov_rows)
    # noise paired probe same contexts
    ncode=byte_probe_codes(core,world,world.noisy,2); before={}
    for arm in ARMS:
        m=SumMetric()
        for i,(zr,ze) in ncode.items():m.add(panel.predict(arm,zr),int(world.labels[i]))
        before[arm]=m.row()
    for i in world.noisy:
        wrong=ord('a')+(int(world.labels[i])-ord('a')+1)%24; process_record(world.record(i,wrong,'one_off_noise',1,1,0),None)
    for arm in ARMS:
        m=SumMetric()
        for i,(zr,ze) in ncode.items():m.add(panel.predict(arm,zr),int(world.labels[i]))
        aft=m.row(); noise.append({'seed':seed,'task':'BYTE256','load':load,'arm':arm,'before_accuracy':before[arm]['accuracy'],'after_accuracy':aft['accuracy'],'accuracy_change':aft['accuracy']-before[arm]['accuracy'],'before_bpb':before[arm]['bpb'],'after_bpb':aft['bpb'],'bpb_change':aft['bpb']-before[arm]['bpb']})
    # C
    for ex in range(1,world.reps+1):
        ids=world.acq[(2,ex)]; up=unpaired_map(seed,f'acq:2:{ex}',ids,[world.labels[i] for i in ids])
        for i in ids:process_record(world.record(i,world.labels[i],'acquisition',ex,2,(ex-1)%2),up)
    for c,name in ((0,'A_untouched_after_C_heldout'),(1,'B_after_C_heldout'),(2,'C_after_C_heldout')):
        ids=world.cohort_ids(c) if c else list(range(world.count//2)); byte_probe(panel,core,world,ids,world.labels,2,seed,load,name,probes,markov,markov_rows)
    # revision
    rreps=2 if smoke else 8
    rev_probe=byte_probe_codes(core,world,world.revised,2)
    for ex in range(1,rreps+1):
        ids=world.revb[ex]; up=unpaired_map(seed,f'rev:{ex}',ids,[world.changed[i] for i in ids])
        for i in ids:process_record(world.record(i,world.changed[i],'revision',ex,2,0),up,True)
        if ex in (1,2,4,8):
            for arm in ARMS:
                mn=SumMetric(); oldprob=[]
                for i,(zr,ze) in rev_probe.items():
                    p=panel.predict(arm,zr); new=int(world.changed[i]); old=int(world.labels[i]); mn.add(p,new); oldprob.append(float(p[old]))
                rr=mn.row(); rev.append({'seed':seed,'task':'BYTE256','load':load,'arm':arm,'row_type':'probe','exposure':ex,'new_accuracy':rr['accuracy'],'new_probability':rr['mean_true_probability'],'new_bpb':rr['bpb'],'old_probability':float(np.mean(oldprob))})
    # D
    for ex in range(1,world.reps+1):
        ids=world.acq[(3,ex)]; up=unpaired_map(seed,f'acq:3:{ex}',ids,[world.labels[i] for i in ids])
        for i in ids:process_record(world.record(i,world.labels[i],'acquisition',ex,3,(ex-1)%2),up)
    untouched=list(range(world.count//2))
    finals=[('A_untouched_after_D_trained',untouched,0,world.labels),('A_untouched_after_D_heldout',untouched,2,world.labels),('A_noise_after_D_heldout',world.noisy,2,world.labels),('A_revision_after_D_heldout',world.revised,2,world.changed),
            ('B_after_D_heldout',world.cohort_ids(1),2,world.labels),('C_after_D_heldout',world.cohort_ids(2),2,world.labels),('D_after_D_trained',world.cohort_ids(3),0,world.labels),('D_after_D_heldout',world.cohort_ids(3),2,world.labels)]
    for name,ids,wr,labs in finals:byte_probe(panel,core,world,ids,labs,wr,seed,load,name,probes,markov,markov_rows)
    # localization
    loc_codes=byte_probe_codes(core,world,untouched,2); loc=[]
    for arm in REAL_ARMS:
        base=panel.mem[arm]; variants={'intact':base,'reset':Memory()}; sh=base.clone(); rg=rng_for(seed,f'byte-syn-shuffle:{arm}')
        for j in range(MBON_N):
            ix=np.flatnonzero(KM_POST==j); v=sh.theta[ix].copy(); rg.shuffle(v); sh.theta[ix]=v
        variants['shuffle']=sh
        for lesion,mem in variants.items():
            m=SumMetric()
            for i,(zr,ze) in loc_codes.items():m.add(mem.predict(zr,C),int(world.labels[i]))
            loc.append({'seed':seed,'task':'BYTE256','load':load,'arm':arm,'lesion':lesion,**m.row()})
    cm=[]
    for (arm,sub,cls),m in class_metrics.items():cm.append({'seed':seed,'task':'BYTE256','load':load,'arm':arm,'subset':sub,'byte_class':cls,**m.row()})
    # accounting assertions per arm/subset
    assertions=[]
    for arm in list(ARMS)+['MARKOV2']:
        for sub in ('all','full_context'):
            d={(r['byte_class']):r for r in cm if r['arm']==arm and r['subset']==sub}
            if not d:continue
            nsum=sum(int(d[c]['n']) for c in ('framing','key','target')); lsum=sum(float(d[c]['loss_sum']) for c in ('framing','key','target')); whole=d['whole']
            ok_n=nsum==int(whole['n']); ok_l=abs(lsum-float(whole['loss_sum']))<=1e-8*max(1.,abs(float(whole['loss_sum'])))
            assertions.append({'arm':arm,'subset':sub,'count_ok':ok_n,'loss_ok':ok_l,'class_n_sum':nsum,'whole_n':whole['n'],'class_loss_sum':lsum,'whole_loss_sum':whole['loss_sum']})
            assert ok_n and ok_l
    state=[]; updates=[]; graph_bytes=sum(x.nbytes for x in (PN_IDS,KC_IDS,MBON_IDS,PK_PRE,PK_POST,PK_COUNT,KM_PRE,KM_POST,KM_COUNT,PK_SCALE)); adaptor_bytes=core.idx.nbytes+core.sgn.nbytes
    for arm in ARMS:
        mem=panel.mem.get(arm); updates.append({'seed':seed,'task':'BYTE256','load':load,'arm':arm,**(mem.stats() if mem else Memory().stats())}); state.append({'seed':seed,'task':'BYTE256','load':load,'arm':arm,'learned_bytes':0 if arm=='NOLEARN' else len(KM_PRE)*8,
            'kc_transient_bytes':KC_N*8,'eligibility_transient_bytes':KC_N*8 if 'ELIG' in arm else 0,'codebook_bytes':C.nbytes,'graph_fixed_bytes':graph_bytes,'adaptor_fixed_bytes':adaptor_bytes,'feature_cache_bytes_actual':core.approx_cache_bytes(),'feature_cache_entry_cap':core.cache_cap})
    state.append({'seed':seed,'task':'BYTE256','load':load,'arm':'MARKOV2','learned_bytes':markov.bytes(),'kc_transient_bytes':0,'eligibility_transient_bytes':0,'codebook_bytes':0,'graph_fixed_bytes':0,'adaptor_fixed_bytes':0,'feature_cache_cap_bytes':0})
    return {'identity':EXPERIMENT_NAMESPACE,'seed':seed,'task':'BYTE256','load':load,'effective_load':world.count*4,'smoke':bool(smoke),'prequential':preq,'probes':probes,'noise':noise,'revision':rev,'localization':loc,'byte_class_metrics':cm,'markov_rows':markov_rows,'accounting':assertions,
            'updates':updates,'state_costs':state,'sample_budget':{'seed':seed,'task':'BYTE256','load':load,'identities':world.count*4,'teacher_events':global_obs,'raw_byte_observations':global_obs,'target_acquisition_events':4*world.count*world.reps,'records':int(global_obs/14)},
            'cache':{'hits':core.hits,'misses':core.misses,'entries':len(core.cache),'bytes':core.approx_cache_bytes()},'elapsed_seconds':time.perf_counter()-t0,'peak_rss':rss_bytes(),'codebook_rank':int(np.linalg.matrix_rank(C))}

# ----------------------------- aggregation/statistics -------------------------
def gzip_csv(path,rows):
    rows=list(rows); path=Path(path); path.parent.mkdir(parents=True,exist_ok=True)
    if not rows:
        with gzip.open(path,'wt') as f:f.write('')
        return
    fields=[]
    for r in rows:
        for k in r:
            if k not in fields:fields.append(k)
    with gzip.open(path,'wt',newline='') as f:
        w=csv.DictWriter(f,fieldnames=fields); w.writeheader(); w.writerows(rows)

def mean_ci(vals):
    vals=np.asarray([float(x) for x in vals if x is not None and math.isfinite(float(x))],dtype=float); n=len(vals)
    if n==0:return {'n':0,'mean':None,'low':None,'high':None,'sd':None,'p':None}
    m=float(vals.mean()); sd=float(vals.std(ddof=1)) if n>1 else 0.
    if n>1:
        if sd<1e-15:
            p=1.0 if abs(m)<1e-15 else 0.0
            return {'n':n,'mean':m,'low':m,'high':m,'sd':sd,'p':p}
        tcrit=float(_scipy_stats.t.ppf(.975,n-1)) if _scipy_stats else 1.96; h=tcrit*sd/math.sqrt(n)
        p=float(_scipy_stats.ttest_1samp(vals,0.).pvalue) if _scipy_stats else math.erfc(abs(m/(sd/math.sqrt(n)+1e-300))/math.sqrt(2))
        return {'n':n,'mean':m,'low':m-h,'high':m+h,'sd':sd,'p':p}
    return {'n':1,'mean':m,'low':None,'high':None,'sd':0.,'p':None}

def bootstrap_ci(vals,seed=515100,B=5000):
    a=np.asarray(vals,dtype=float)
    if not len(a):return (None,None)
    rg=np.random.default_rng(seed+len(a)); means=np.empty(B)
    for b in range(B):means[b]=a[rg.integers(0,len(a),len(a))].mean()
    return float(np.quantile(means,.025)),float(np.quantile(means,.975))

def holm(rows):
    valid=[(i,r['p']) for i,r in enumerate(rows) if r.get('p') is not None and math.isfinite(float(r['p']))]; m=len(valid)
    if not m:return rows
    valid.sort(key=lambda x:x[1]); adj=[None]*len(rows); prev=0.
    for rank,(i,p) in enumerate(valid):
        v=min(1.,(m-rank)*float(p)); v=max(prev,v); prev=v; adj[i]=v
    for i,r in enumerate(rows):r['holm_p']=adj[i]
    return rows

def aggregate_all(results,out_dir,science=True):
    out=Path(out_dir); preq=[]; probes=[]; noise=[]; revision=[]; loc=[]; bcm=[]; markov=[]; state=[]; updates=[]; budgets=[]; runtime=[]; assertions=[]
    for r in results:
        preq+=r.get('prequential',[]); probes+=r.get('probes',[]); noise+=r.get('noise',[]); revision+=r.get('revision',[]); loc+=r.get('localization',[]); bcm+=r.get('byte_class_metrics',[]); markov+=r.get('markov_rows',[]); state+=r.get('state_costs',[]); updates+=r.get('updates',[]); budgets.append(r.get('sample_budget',{})); assertions+=r.get('accounting',[])
        runtime.append({'seed':r['seed'],'task':r['task'],'load':r['load'],'elapsed_seconds':r['elapsed_seconds'],'peak_rss':r['peak_rss'],'effective_load':r['effective_load'],'smoke':r['smoke']})
    gzip_csv(out/'PREQUENTIAL_ASSOCIATION.csv.gz',preq); write_csv(out/'FIRST_RETURN.csv',[x for x in probes if x['checkpoint']=='A_first_return_after_B']); write_csv(out/'COHORT_RETENTION.csv',probes); write_csv(out/'NOISE_RESISTANCE.csv',noise); write_csv(out/'REVISION_CURVES.csv',revision); write_csv(out/'REVISED_AFTER_D.csv',[x for x in probes if x['checkpoint']=='A_revision_after_D_heldout']); write_csv(out/'STATE_LOCALIZATION.csv',loc); write_csv(out/'BYTE_CLASS_METRICS.csv',bcm); write_csv(out/'BYTE_ASSOCIATION_PROBES.csv',[x for x in probes if x['task']=='BYTE256']); write_csv(out/'MARKOV_BASELINE.csv',markov+[{'kind':'stream',**x} for x in bcm if x.get('arm')=='MARKOV2']); write_csv(out/'STATE_COSTS.csv',state); write_csv(out/'UPDATE_NORMS.csv',updates); write_csv(out/'SAMPLE_BUDGET.csv',budgets); write_csv(out/'RUNTIME.csv',runtime); atomic_json(out/'BYTE_ACCOUNTING_ASSERTIONS.json',{'rows':assertions,'all_pass':all(x['count_ok'] and x['loss_ok'] for x in assertions) if assertions else True})
    # acquisition curves
    grp=collections.defaultdict(list)
    for x in preq:grp[(x['seed'],x['task'],x['load'],x['arm'],x['cohort'],x['exposure_index'])].append(x)
    curves=[]
    for key,rr in sorted(grp.items()):
        curves.append({'seed':key[0],'task':key[1],'load':key[2],'arm':key[3],'cohort':key[4],'exposure_index':key[5],'n':len(rr),'accuracy':float(np.mean([z['correct'] for z in rr])),'mean_loss_bits':float(np.mean([z['loss_bits'] for z in rr])),'mean_true_probability':float(np.mean([z['true_probability'] for z in rr]))})
    write_csv(out/'ACQUISITION_CURVES.csv',curves)
    # D80 per seed/condition/cohort
    cdict={(r['seed'],r['task'],r['load'],r['arm'],r['cohort'],r['exposure_index']):r for r in curves}; crit=[]
    keys=sorted(set(k[:5] for k in cdict))
    for k in keys:
        vals={e:cdict[k+(e,)] for e in range(1,9) if k+(e,) in cdict}; cross=None
        for e in range(1,8):
            if e in vals and e+1 in vals and vals[e]['accuracy']>=.8 and vals[e+1]['accuracy']>=.8:cross=e;break
        late=(cross is None and 8 in vals and vals[8]['accuracy']>=.8); d80=cross if cross is not None else 8
        crit.append({'seed':k[0],'task':k[1],'load':k[2],'arm':k[3],'cohort':k[4],'crossing_exposure':cross,'prior_exposures_at_crossing':cross-1 if cross else None,'confirmed_at_exposure':cross+1 if cross else None,'late_unconfirmed_crossing':bool(late),'right_censored':cross is None,'D80':d80})
    write_csv(out/'EXPOSURES_TO_CRITERION.csv',crit)
    # seed-condition summary acquisition metrics
    acq=[]
    for key in sorted(set((r['seed'],r['task'],r['load'],r['arm']) for r in curves)):
        rr=[r for r in curves if (r['seed'],r['task'],r['load'],r['arm'])==key]; losses=[r['mean_loss_bits'] for r in rr]; dr=[r['D80'] for r in crit if (r['seed'],r['task'],r['load'],r['arm'])==key]
        acq.append({'seed':key[0],'task':key[1],'load':key[2],'arm':key[3],'acquisition_loss':float(np.mean(losses)) if losses else None,'D80':float(np.mean(dr)) if dr else None,'cohorts_crossing':sum(not r['right_censored'] for r in crit if (r['seed'],r['task'],r['load'],r['arm'])==key)})
    # phenotype by condition (CUE thresholds + descriptive BYTE)
    def probe_map(seed,task,load,arm,cp):
        q=[r for r in probes if r['seed']==seed and r['task']==task and r['load']==load and r['arm']==arm and r['checkpoint']==cp]; return q[0] if q else None
    ph=[]
    for task in TASKS:
      for load in LOADS:
       for arm in REAL_ARMS:
        seeds=sorted(set(r['seed'] for r in results if r['task']==task and r['load']==load))
        def vals(cp,key='accuracy'):
            return [probe_map(s,task,load,arm,cp)[key] for s in seeds if probe_map(s,task,load,arm,cp)]
        row={'task':task,'load':load,'arm':arm,'n_seeds':len(seeds)}
        for cp,name in [('after_A_trained','A_initial'),('A_first_return_after_B','A_first_return'),('A_untouched_after_D_trained','A_final_trained'),('A_untouched_after_D_heldout','A_final_heldout'),('D_after_D_trained','D_final_trained'),('D_after_D_heldout','D_final_heldout'),('A_revision_after_D_heldout','revision_after_D')]:
            a=mean_ci(vals(cp)); row[name+'_accuracy']=a['mean']; b=mean_ci(vals(cp,'bpb')); row[name+'_bpb']=b['mean']
        # noise/rev/localization
        nn=[r for r in noise if r['task']==task and r['load']==load and r['arm']==arm]; row['noise_after_accuracy']=float(np.mean([r['after_accuracy'] for r in nn])) if nn else None; row['noise_accuracy_change']=float(np.mean([r['accuracy_change'] for r in nn])) if nn else None
        rv=[r for r in revision if r['task']==task and r['load']==load and r['arm']==arm and r.get('row_type')=='probe' and int(r['exposure'])==8]; row['revision8_accuracy']=float(np.mean([r['new_accuracy'] for r in rv])) if rv else None; row['revision8_new_minus_old_probability']=float(np.mean([r['new_probability']-r['old_probability'] for r in rv])) if rv else None
        ll=[r for r in loc if r['task']==task and r['load']==load and r['arm']==arm]; by=collections.defaultdict(dict)
        for r in ll:by[r['seed']][r['lesion']]=r
        drops=[v['intact']['accuracy']-v['reset']['accuracy'] for v in by.values() if 'intact'in v and'reset'in v]; row['synapse_reset_drop']=float(np.mean(drops)) if drops else None
        # CUE phenotype checks
        if task=='CUE8' and seeds and science:
            nl='NOLEARN'; up='UNPAIRED-ELIG' if arm=='ELIG-WRITE' else 'UNPAIRED-REF'
            first=vals('A_first_return_after_B'); first_n=[probe_map(s,task,load,nl,'A_first_return_after_B')['accuracy'] for s in seeds]; held=vals('A_untouched_after_D_heldout'); held_n=[probe_map(s,task,load,nl,'A_untouched_after_D_heldout')['accuracy'] for s in seeds]; held_u=[probe_map(s,task,load,up,'A_untouched_after_D_heldout')['accuracy'] for s in seeds]
            locci=mean_ci(drops); row['phenotype_pass']=bool(row['A_initial_accuracy']>=.8 and min(vals('after_A_trained'))>=.6 and row['D_final_trained_accuracy']>=.8 and min(vals('D_after_D_trained'))>=.6 and row['A_first_return_accuracy']>=.6 and mean_ci(np.array(first)-np.array(first_n))['low']>0 and mean_ci(np.array(first)-np.array(first_n))['mean']>=.3 and row['A_final_trained_accuracy']>=.5 and row['A_final_heldout_accuracy']>=.4 and mean_ci(np.array(held)-np.array(held_n))['mean']>=.2 and mean_ci(np.array(held)-np.array(held_n))['low']>0 and mean_ci(np.array(held)-np.array(held_u))['mean']>=.2 and mean_ci(np.array(held)-np.array(held_u))['low']>0 and row['noise_after_accuracy']>=.5 and row['noise_accuracy_change']>=-.25 and row['revision8_accuracy']>=.6 and row['revision8_new_minus_old_probability']>0 and locci['mean']>=.25 and locci['low']>0)
        else:row['phenotype_pass']=None
        ph.append(row)
    write_csv(out/'PHENOTYPE_BY_CONDITION.csv',ph); write_csv(out/'OPERATING_ENVELOPE.csv',ph)
    # primary contrasts ELIG-REF per condition
    family_rows={'acquisition_loss':[],'D80':[],'delayed_old_bpb':[]}
    contrast_rows=[]
    for task in TASKS:
      for load in LOADS:
        seeds=sorted(set(r['seed'] for r in results if r['task']==task and r['load']==load))
        amap={(r['seed'],r['arm']):r for r in acq if r['task']==task and r['load']==load}
        for metric in ('acquisition_loss','D80'):
            dif=[amap[(s,'ELIG-WRITE')][metric]-amap[(s,'V50-REF')][metric] for s in seeds if (s,'ELIG-WRITE') in amap and (s,'V50-REF') in amap]
            stt=mean_ci(dif); blo,bhi=bootstrap_ci(dif); row={'family':metric,'task':task,'load':load,'metric':metric,'direction':'ELIG_minus_REF',**stt,'bootstrap_low':blo,'bootstrap_high':bhi};family_rows[metric].append(row);contrast_rows.append(row)
        dif=[]
        for s in seeds:
            e=probe_map(s,task,load,'ELIG-WRITE','A_untouched_after_D_heldout');r=probe_map(s,task,load,'V50-REF','A_untouched_after_D_heldout')
            if e and r:dif.append(e['bpb']-r['bpb'])
        stt=mean_ci(dif); blo,bhi=bootstrap_ci(dif); row={'family':'delayed_old_bpb','task':task,'load':load,'metric':'delayed_old_bpb','direction':'ELIG_minus_REF',**stt,'bootstrap_low':blo,'bootstrap_high':bhi};family_rows['delayed_old_bpb'].append(row);contrast_rows.append(row)
    for fam in family_rows:holm(family_rows[fam])
    # merge holm values back
    lookup={(r['family'],r['task'],r['load']):r for fam in family_rows.values() for r in fam}
    for r in contrast_rows:r['holm_p']=lookup[(r['family'],r['task'],r['load'])].get('holm_p')
    write_csv(out/'SAMPLE_EFFICIENCY_CONTRASTS.csv',contrast_rows)
    # task/load contrasts and eligibility x load
    tl=[]
    for task in TASKS:
      for arm in REAL_ARMS:
        seeds=sorted(set(r['seed'] for r in results if r['task']==task))
        amap={(r['seed'],r['load'],r['arm']):r for r in acq if r['task']==task}
        for met in ('acquisition_loss','D80'):
            dif=[amap[(s,256,arm)][met]-amap[(s,128,arm)][met] for s in seeds if (s,256,arm) in amap and(s,128,arm) in amap];tl.append({'task':task,'arm':arm,'metric':met,'contrast':'load256_minus_128',**mean_ci(dif)})
      # interaction
      for met in ('acquisition_loss','D80'):
        dif=[]
        amap={(r['seed'],r['load'],r['arm']):r for r in acq if r['task']==task}
        seeds=sorted(set(r['seed'] for r in results if r['task']==task))
        for s in seeds:
            try:d256=amap[(s,256,'ELIG-WRITE')][met]-amap[(s,256,'V50-REF')][met];d128=amap[(s,128,'ELIG-WRITE')][met]-amap[(s,128,'V50-REF')][met];dif.append(d256-d128)
            except KeyError:pass
        tl.append({'task':task,'arm':'ELIG-WRITE_vs_REF','metric':met,'contrast':'eligibility_x_load','mean':mean_ci(dif)['mean'],'low':mean_ci(dif)['low'],'high':mean_ci(dif)['high'],'n':len(dif)})
    write_csv(out/'TASK_LOAD_CONTRASTS.csv',tl)
    # recommendation based on fresh CUE8/128 evidence only
    cue128=[r for r in contrast_rows if r['task']=='CUE8' and r['load']==128]; cm={r['metric']:r for r in cue128}; eph=[r for r in ph if r['task']=='CUE8' and r['load']==128 and r['arm']=='ELIG-WRITE'][0] if any(r['task']=='CUE8' and r['load']==128 and r['arm']=='ELIG-WRITE' for r in ph) else None
    useful=bool(cm.get('delayed_old_bpb') and cm['delayed_old_bpb'].get('mean') is not None and cm['delayed_old_bpb']['mean']<=-.03 and cm['delayed_old_bpb']['high'] is not None and cm['delayed_old_bpb']['high']<0)
    acq_ok=bool(cm.get('acquisition_loss') and cm['acquisition_loss'].get('mean') is not None and cm['acquisition_loss']['high'] is not None and cm['acquisition_loss']['high']<=.02)
    # revision cost paired
    seeds=sorted(set(r['seed'] for r in results if r['task']=='CUE8' and r['load']==128)); rdiff=[]
    for s in seeds:
        e=[r for r in revision if r['seed']==s and r['task']=='CUE8' and r['load']==128 and r['arm']=='ELIG-WRITE' and r.get('row_type')=='probe' and int(r['exposure'])==8];q=[r for r in revision if r['seed']==s and r['task']=='CUE8' and r['load']==128 and r['arm']=='V50-REF' and r.get('row_type')=='probe' and int(r['exposure'])==8]
        if e and q:rdiff.append(e[0]['new_accuracy']-q[0]['new_accuracy'])
    rc=mean_ci(rdiff); rev_ok=bool(rc['low'] is not None and rc['low']>=-.05)
    rec='ADOPT_ELIG_WITHIN_CUE128' if useful and acq_ok and rev_ok and eph and eph.get('phenotype_pass') else ('ELIG_TRADEOFF_OR_UNCONFIRMED' if eph and eph.get('phenotype_pass') else 'RETAIN_V50_REF')
    if (not science) or len(results)<64: rec='PROVISIONAL_'+rec
    write_csv(out/'CONFIGURATION_RECOMMENDATION.csv',[{'recommendation':rec,'elig_useful_delayed':useful,'acquisition_noninferior_0p02':acq_ok,'revision_noninferior_0p05':rev_ok,'elig_cue128_phenotype_pass':eph.get('phenotype_pass') if eph else None,'revision8_diff_mean':rc['mean'],'revision8_diff_low':rc['low'],'revision8_diff_high':rc['high']}])
    # summary
    lines=['# V51 — Frozen-core scope and eligibility confirmation','',f'Completed jobs: {len(results)} / 64','']
    for r in ph:
        lines.append(f"- {r['task']} load {r['load']} {r['arm']}: A_final_heldout={r.get('A_final_heldout_accuracy')}, D_final={r.get('D_final_trained_accuracy')}, phenotype_pass={r.get('phenotype_pass')}")
    lines+=['',f'Configuration recommendation: `{rec}`','']
    (out/'SUMMARY.md').write_text('\n'.join(lines))
    return {'phenotype':ph,'contrasts':contrast_rows,'recommendation':rec}

# ----------------------------- jobs / CLI -------------------------------------
def job_key(task,load,seed,smoke):return sha_json({'namespace':EXPERIMENT_NAMESPACE,'version':VERSION,'source':source_sha(),'design':DESIGN_SHA256,'graph':GRAPH_PAYLOAD_SHA256,'task':task,'load':int(load),'seed':int(seed),'smoke':bool(smoke),'feature_rule':'v50-leak+elig0.72','generator':'v51-preserve-v50'})
def job_file(out,task,load,seed):return Path(out)/'jobs'/f'{task}_L{int(load)}_S{int(seed)}.json.gz'
def run_one(task,load,seed,smoke,out):
    p=job_file(out,task,load,seed); ident=job_key(task,load,seed,smoke)
    if p.exists():
        x=load_gzip_json(p)
        if x.get('identity')==ident:
            print(f'[reuse] {task} L{load} seed {seed}',flush=True); return x['result']
        stale=p.with_suffix(p.suffix+f'.stale-{int(time.time())}');p.rename(stale)
    print(f'[start] {task} L{load} seed {seed}',flush=True)
    r=cue_trial(seed,load,smoke) if task=='CUE8' else byte_trial(seed,load,smoke)
    atomic_gzip_json(p,{'identity':ident,'result':r});print(f'[done] {task} L{load} seed {seed} {r["elapsed_seconds"]:.1f}s',flush=True);return r

def _worker_v51(a):return run_one(*a)
def run_jobs(tasks,loads,seeds,smoke,out,workers):
    Path(out,'jobs').mkdir(parents=True,exist_ok=True)
    # interleave conditions within each seed to avoid seeing all easy cells first
    args=[]
    for s in seeds:
        for load in loads:
            for task in tasks:args.append((task,load,int(s),smoke,str(out)))
    if workers<=1:return [_worker_v51(a) for a in args]
    ctx=mp.get_context('spawn')
    with concurrent.futures.ProcessPoolExecutor(max_workers=workers,mp_context=ctx) as ex:return list(ex.map(_worker_v51,args))

def load_cached(out,tasks,loads,seeds,smoke):
    rr=[]
    for s in seeds:
      for l in loads:
       for t in tasks:
        p=job_file(out,t,l,s)
        if p.exists():
            x=load_gzip_json(p)
            if x.get('identity')==job_key(t,l,s,smoke):rr.append(x['result'])
    return rr

def implementation_audit():
    return {'version':VERSION,'namespace':EXPERIMENT_NAMESPACE,'source_sha256':source_sha(),'design_sha256':DESIGN_SHA256,'v50_source_sha256_expected':V50_SOURCE_SHA256,'graph_payload_sha256':GRAPH_PAYLOAD_SHA256,
            'raw_graph_counts':{'pn':len(PN_IDS),'kc':len(KC_IDS),'mbon':len(MBON_IDS),'pn_kc_edges':len(PK_PRE),'pn_kc_count_sum':int(round(PK_COUNT.sum())),'kc_mbon_edges':len(KM_PRE),'kc_mbon_count_sum':int(round(KM_COUNT.sum()))},
            'eligibility_contract':'a_t=0.72*a_(t-1)+S(s_t); write=S(0.72*a_4); read=S(s_4)','blank_scalar_cancels_under_S':True,'eta':ETA,'rho':RHO,'tau':TAU,'kc_active':KC_ACTIVE,
            'science_seeds':list(SCIENCE_SEEDS),'historical_seed_overlap':bool(set(SCIENCE_SEEDS)&set(range(50901,50917)))}

def self_test_v51():
    aud=implementation_audit(); assert aud['raw_graph_counts']=={'pn':699,'kc':4552,'mbon':104,'pn_kc_edges':22417,'pn_kc_count_sum':168315,'kc_mbon_edges':15523,'kc_mbon_count_sum':28415}
    # V50 reference fixture
    w=CueWorldV51(50971,128,False); sens=EligibilitySensory(); zr,ze=sens.cue_features(w.frames(0,0,0)); ix=np.flatnonzero(zr); assert tuple(ix[:20])==_V50_FIXTURE_IDX; assert abs(float(zr.sum())-_V50_FIXTURE_SUM)<1e-10
    C=outcome_codebook(50971,8,'outcome-code'); mem=Memory(); p=mem.predict(zr,C); assert np.allclose(p,np.ones(8)/8); mem.update(zr,int(w.labels[0]),C,p); assert abs(float(np.linalg.norm(mem.theta))-_V50_FIXTURE_THETA_NORM)<1e-10
    # eligibility exact algebra fixture
    state=np.zeros(KC_N); acc=np.zeros(KC_N)
    for pn in w.frames(0,0,0):
        a=np.tanh(sens.pn_to_drive(pn));state=RHO*state+(1-RHO)*a;acc=ELIG_DECAY*acc+sens._sparse(state)
    manual=sens._sparse(ELIG_DECAY*acc); assert np.allclose(manual,ze)
    # only write vector differs: fresh equal weights predict identically
    mr=Memory();me=Memory();pr=mr.predict(zr,C);pe=me.predict(zr,C);assert np.array_equal(pr,pe);mr.update(zr,0,C,pr);me.update(ze,0,C,pe);assert not np.allclose(mr.theta,me.theta)
    # tiny cue+byte cells
    cr=cue_trial(51671,128,True);br=byte_trial(51671,128,True);assert all(x['count_ok'] and x['loss_ok'] for x in br['accounting'])
    return {'audit':aud,'v50_fixture':{'first20':ix[:20].tolist(),'sum':float(zr.sum()),'theta_norm':float(np.linalg.norm(mem.theta))},'elig_support_overlap':int(np.intersect1d(np.flatnonzero(zr),np.flatnonzero(ze)).size),'cue_smoke_seconds':cr['elapsed_seconds'],'byte_smoke_seconds':br['elapsed_seconds']}

def protocol_text():
    return 'V51-SCOPE-ELIG preserves the released V50 raw-BANC leaky associative core and crosses task (CUE8/BYTE256) with load (128/256). The only nominated learning addition is multi-frame eligibility-shaped writing. V50-REF and ELIG-WRITE read from the identical final KC code. Causal controls are NOLEARN, UNPAIRED-REF, and UNPAIRED-ELIG. Seed is the inferential unit. BYTE256 role labels are evaluator-only and never enter deployable learners.\n'

def make_manifest(out,seeds,tasks,loads,stage,results,smoke):
    m={'namespace':EXPERIMENT_NAMESPACE,'version':VERSION,'source_sha256':source_sha(),'design_sha256':DESIGN_SHA256,'graph_payload_sha256':GRAPH_PAYLOAD_SHA256,'v50_source_sha256':V50_SOURCE_SHA256,'science_seeds':list(seeds),'tasks':list(tasks),'loads':list(loads),'stage':stage,'smoke':bool(smoke),'completed_jobs':len(results),'expected_jobs':len(seeds)*len(tasks)*len(loads),'platform':platform.platform(),'python':sys.version,'numpy':np.__version__,'scipy':getattr(__import__('scipy'),'__version__',None) if _scipy_stats else None}
    atomic_json(Path(out)/'MANIFEST.json',m);return m

def package(out):
    out=Path(out); dest=out/'v51_results_upload.zip'; names=['SUMMARY.md','MANIFEST.json','IMPLEMENTATION_AUDIT.json','OPERATING_ENVELOPE.csv','PHENOTYPE_BY_CONDITION.csv','CONFIGURATION_RECOMMENDATION.csv','PREQUENTIAL_ASSOCIATION.csv.gz','ACQUISITION_CURVES.csv','EXPOSURES_TO_CRITERION.csv','SAMPLE_EFFICIENCY_CONTRASTS.csv','TASK_LOAD_CONTRASTS.csv','FIRST_RETURN.csv','COHORT_RETENTION.csv','NOISE_RESISTANCE.csv','REVISION_CURVES.csv','REVISED_AFTER_D.csv','STATE_LOCALIZATION.csv','BYTE_CLASS_METRICS.csv','BYTE_ASSOCIATION_PROBES.csv','MARKOV_BASELINE.csv','BYTE_ACCOUNTING_ASSERTIONS.json','STATE_COSTS.csv','UPDATE_NORMS.csv','SAMPLE_BUDGET.csv','RUNTIME.csv','PROTOCOL.md']
    with zipfile.ZipFile(dest,'w',zipfile.ZIP_DEFLATED) as z:
        for n in names:
            p=out/n
            if p.exists():z.write(p,n)
    return dest

def main_v51(argv=None):
    ap=argparse.ArgumentParser(description='V51 frozen-core scope and eligibility confirmation')
    ap.add_argument('--stage',choices=('all','cue','byte','aggregate'),default='all');ap.add_argument('--out-dir',type=Path,default=Path('v51_results'));ap.add_argument('--workers',type=int,default=4);ap.add_argument('--seeds',type=int,nargs='*');ap.add_argument('--loads',type=int,nargs='*',choices=(128,256));ap.add_argument('--smoke',action='store_true');ap.add_argument('--self-test',action='store_true');args=ap.parse_args(argv)
    if args.self_test:
        print(json.dumps(self_test_v51(),indent=2,default=str));return 0
    seeds=tuple(args.seeds) if args.seeds else (ENGINEERING_SEEDS[:2] if args.smoke else SCIENCE_SEEDS); loads=tuple(args.loads) if args.loads else LOADS; tasks=TASKS if args.stage in ('all','aggregate') else (('CUE8',) if args.stage=='cue' else ('BYTE256',))
    out=args.out_dir;out.mkdir(parents=True,exist_ok=True);(out/'PROTOCOL.md').write_text(protocol_text());atomic_json(out/'IMPLEMENTATION_AUDIT.json',implementation_audit())
    if args.stage=='aggregate':results=load_cached(out,TASKS,loads,seeds,args.smoke)
    else:results=run_jobs(tasks,loads,seeds,args.smoke,out,args.workers)
    # Aggregate all currently valid cached cells, not only this stage, so partial reports are explicit.
    allres=load_cached(out,TASKS,LOADS,seeds,args.smoke); summary=aggregate_all(allres,out,science=not(args.smoke or args.seeds is not None)) if allres else None
    make_manifest(out,seeds,TASKS,LOADS,args.stage,allres,args.smoke);dest=package(out)
    print(json.dumps({'namespace':EXPERIMENT_NAMESPACE,'completed_jobs':len(allres),'expected_jobs':len(seeds)*4,'recommendation':summary.get('recommendation') if summary else None,'upload':str(dest),'out_dir':str(out)},indent=2));return 0

if __name__=='__main__':raise SystemExit(main_v51())
